// project initialization 
namespace SpriteKind {
    export const Title = SpriteKind.create()
    export const Background = SpriteKind.create()
}

let currentScene = 0
let score = 0
let text = textsprite.create("", 0, 10)
text.setKind(SpriteKind.Title)

let scoreText = textsprite.create("")
scoreText.setKind(SpriteKind.Title)

// game set up
callScene(currentScene)
createVariable()

function callScene(sceneNum: number) {
    let playerSprite = sprites.create(assets.image`player`, SpriteKind.Player)
    let goal = sprites.create(assets.image`heart`, SpriteKind.Food)

    if (sceneNum == 0) {
        // splash screen
        let background = sprites.create(assets.image`splashScreen1`, SpriteKind.Background)
        let backgroundAnim= sprites.create(assets.image`mountainLayer`, SpriteKind.Background)
        animation.runImageAnimation(backgroundAnim, assets.animation`splashAnim`, 500, true)

        // text sprite
        text.setText('Labyrinth Legends')
        text.setMaxFontHeight(10)
        text.setOutline(2, 0)
        text.setPosition(80, 25)
        text.z = 3

        // player sprite
        playerSprite.z = 2
        playerSprite.setPosition(82, 90)
        animation.runImageAnimation(playerSprite, assets.animation`playerAnim`, 200, true)

        // choice menu
        choiceMenu()
        sprites.destroyAllSpritesOfKind(SpriteKind.Background)
        sprites.destroy(playerSprite)
        sprites.destroy(goal)
    }
    else if (sceneNum == 1) {
        tiles.setCurrentTilemap(assets.tilemap`level1`)
        tiles.placeOnRandomTile(playerSprite, assets.tile`spawnTile1`)
        tiles.placeOnRandomTile(goal, assets.tile`spawnTile1`)
        controller.moveSprite(playerSprite, 100, 100)
    } else if (sceneNum == 2) {
        tiles.setCurrentTilemap(assets.tilemap`level2`)
        tiles.placeOnRandomTile(playerSprite, assets.tile`spawnTile2`)
        tiles.placeOnRandomTile(goal, assets.tile`spawnTile2`)
        controller.moveSprite(playerSprite, 100, 100)
    } else if (sceneNum == 3) {
        // win screen
        tiles.setCurrentTilemap(tilemap`level3`)
        scene.setBackgroundImage(assets.image`splashScreen`)
        text.setText("You Win!")
        text.setMaxFontHeight(10)
        // player sprite
        playerSprite.setPosition(82, 90)
        animation.runImageAnimation(playerSprite, assets.animation`playerAnim`, 200, true)
        // play again
        effects.confetti.startScreenEffect()
        music.play(music.melodyPlayable(music.powerUp), music.PlaybackMode.UntilDone)
        controller.pauseUntilAnyButtonIsPressed()
        game.ask("Play Again?")
        effects.confetti.endScreenEffect()
        choiceMenu()
        sprites.destroy(playerSprite)
        sprites.destroy(goal)
    }
}

function choiceMenu() {
    text.setText('Choose a Level')
    text.setMaxFontHeight(8)
    text.setOutline(2, 1)
    text.setPosition(80, 25)
    story.showPlayerChoices("Level 1", "Level 2")
    if (story.checkLastAnswer("Level 1")) {
        currentScene = 1
    } else if (story.checkLastAnswer("Level 2")) {
        currentScene = 2
    }
    callScene(currentScene)
}

function createVariable() {
    score = 0
    scoreText = textsprite.create("score", 1, 10)
    scoreText.setBorder(1, 6)
    scoreText.setIcon(assets.image`star`)
    scoreText.setPosition(15, 10)
}

sprites.onOverlap(SpriteKind.Player, SpriteKind.Food, function (sprite: Sprite, otherSprite: Sprite) {
    sprites.destroy(sprite)
    sprites.destroy(otherSprite)
    score++
    scoreText.setText("score")
    currentScene = 3
    callScene(currentScene)
})
